use vstd::prelude::*;

verus! {
    // Append a leading 0.0 to the front of the input vector `c`,
    // preserving the order of all elements of `c`.
    //
    // Specifications:
    //  - The output has length exactly one more than the input.
    //  - The 0-th element of the output is exactly 0.0.
    //  - For each index i in 0..c.len(), output[i+1] == c[i].
    fn polymulx(c: Vec<f32>) -> Vec<f32>
        ensures
            // Length is one greater than the input
            result.len() == c.len() + 1,
        ensures
            // First element is exactly 0.0
            result[0] == 0.0,
        ensures
            // Every element of c is copied in order, shifted by one
            forall |i: usize|
                i < c.len() ==>
                result[i + 1] == c[i]
    {
        let n: usize = c.len();
        // Pre-allocate capacity for efficiency
        let mut result: Vec<f32> = Vec::with_capacity(n + 1);
        // Push the leading zero
        result.push(0.0);

        let mut i: usize = 0;
        // Loop invariant tracks how many elements of `c` have been copied so far.
        // After i iterations, result.len() == i + 1 (the leading zero plus i copied elements),
        // and for all k < i, result[k+1] == c[k].
        while i < n
            invariant
                // The counter stays in range [0, n]
                i <= n,
            invariant
                // The result vector has exactly i+1 elements so far
                result.len() == i + 1,
            invariant
                // The first element remains 0.0 throughout
                result[0] == 0.0,
            invariant
                // Already-copied prefix property
                forall |k: usize|
                    k < i ==>
                    result[k + 1] == c[k],
            decreases
                // A variant to show termination
                n - i
        {
            // Copy the next element of `c` into `result`
            result.push(c[i]);
            i = i + 1;
        }

        // At this point i == n, so result.len() == n + 1,
        // and for all k < n, result[k+1] == c[k].
        result
    }
}

